// The stage a problem, and an idea, is at, worked out from the records
// and, when the board is known, which of its issues are in the app; never
// stored. A problem:
//
//   Heard (or Assumed, for a problem assumed from an idea) → Trying ideas
//   → Building → In the app → Solved, or Didn't work at the end.
//
// - Solved: a ticket for it was answered "yes, it worked".
// - In the app: a ticket for it, not answered yes or no, is closed or in
//   the board's last column ("In the app"), or was answered "didn't check".
// - Building: a ticket for it is open, not answered.
// - Trying ideas: an idea for it is being explored (versions or not).
// - Didn't work: a ticket for it was answered no, or an idea for it did not
//   work, and nothing else for it is under way.
// - Heard: none of these yet (Assumed when it came from an idea).
export const PROBLEM_STAGES = [
    "assumed",
    "heard",
    "trying",
    "building",
    "inApp",
    "solved",
    "didntWork",
];
// An idea: Idea (no versions yet) → Versions (shared, none sent) → Picked
// (one version has the most picks, no tie) → Building (sent, its ticket
// open) → In the app (closed, merged or in the board's last column, "did
// it work?" not answered, or answered "didn't check") → Worked, or Didn't
// work when every answer was no.
export const IDEA_STAGES = [
    "idea",
    "versions",
    "picked",
    "building",
    "inApp",
    "worked",
    "didntWork",
];
const answersOf = (records) => new Map(records.outcomes.map((o) => [o.issue, o.worked]));
// Where its tickets are: worked, in the app, being built, or none of these
// (no ticket, or every answer no).
function ticketsStage(issues, answers, inApp) {
    if (issues.some((issue) => answers.get(issue) === "yes"))
        return "worked";
    const open = issues.filter((issue) => answers.get(issue) !== "no");
    if (open.some((issue) => inApp.has(issue) || answers.has(issue)))
        return "inApp";
    return open.length > 0 ? "building" : null;
}
export function ideaStage(idea, records, inApp) {
    const issues = records.ticketLinks
        .filter((t) => "idea" in t.from && t.from.idea === idea.id)
        .map((t) => t.issue);
    const tickets = ticketsStage(issues, answersOf(records), inApp);
    if (tickets)
        return tickets;
    if (issues.length > 0)
        return "didntWork";
    const shared = records.versions.filter((v) => v.idea === idea.id && v.sharedAt !== null);
    const most = Math.max(0, ...shared.map((v) => v.picks.length));
    const top = shared.filter((v) => most > 0 && v.picks.length === most);
    if (top.length === 1)
        return "picked";
    return shared.length > 0 ? "versions" : "idea";
}
export function problemStage(problem, records, ideas, inApp) {
    const answers = answersOf(records);
    const tickets = records.ticketLinks.filter((t) => t.problems.includes(problem.id));
    const worked = tickets.map((t) => answers.get(t.issue));
    const where = ticketsStage(tickets.map((t) => t.issue), answers, inApp);
    if (where === "worked")
        return "solved";
    if (where)
        return where;
    const forIt = records.ideas.filter((idea) => idea.problems.includes(problem.id));
    if (forIt.some((idea) => ideas[idea.id] === "exploring"))
        return "trying";
    if (worked.includes("no") ||
        forIt.some((idea) => ideas[idea.id] === "didntWork"))
        return "didntWork";
    return problem.assumed ? "assumed" : "heard";
}
